test("grade merge scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "floor", "0.50");
  await ui.setSetting(pg_uma, "terms", "30");
  await ui.setSetting(pg_uma, "terms-A", "3");
  await ui.setSetting(pg_uma, "cap", "2.00");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  await ui.setSetting(pg_uma, "note-threshold", "2.50");
  expect(await ui.addHoliday(pg_uma, "2026-04-03")).toBe(true);
  expect(await ui.addHoliday(pg_uma, "2026-03-24")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "late")).toBe(true);
  await ui.setSetting(pg_uma, "pot", "100.00");
  await ui.setSetting(pg_uma, "review-sla", "1");
  await ui.setSetting(pg_uma, "clerk-limit-A", "0.50");
  await ui.setSetting(pg_uma, "score-mid", "0");
  await ui.setSetting(pg_uma, "score-high", "5");
  expect(await ui.setRole(pg_uma, "wes", "restricted")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50", "from": "2026-03-16"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "contact": " Ada@x "}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Cam", "share": "70.00", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "20.00"})).toBe(true);
  expect(await ui.addCrew(pg_uma, "C1", "Cam")).toBe(true);
  expect(await ui.addCrewMember(pg_uma, "C1", "Ada")).toBe(true);
  const pl_ben_1 = ui.must(await ui.addPlan(pg_uma, p_ben, {"amount": "25.00", "start": "2026-02-20", "end": "2026-04-30", "every": "10"}));
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "10.25", "tags": "b,a,a"}));
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "10.25", "ref": "R-2", "tags": "b,a,a"}));
  expect(await ui.claimAction(pg_uma, c_ben_0, "open")).toBe(false);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  await ui.showRetired(pg_wes, true);
  await ui.showRetired(pg_wes, true);
  await ui.showRetired(pg_wes, true);
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("person-row-" + p_cam)).toHaveCount(0);

